const nonTerminalSubtree = `-- name: NonTerminalSubtree :many
WITH RECURSIVE subtree(id) AS (
    SELECT process_instances.id FROM process_instances WHERE process_instances.id = ?1
    UNION ALL
    SELECT pi.id FROM process_instances pi JOIN subtree s ON pi.parent_id = s.id
)
SELECT id, process_name, process_version, parent_id,
       call_stack, retry_count, wake_at, status, error_message,
       created_at, updated_at, worker_id, lease_expires_at, wait_state, spawn_task_id,
       input_data, outputs_data, output_data, error_internal, external_data, engine_state, task,
       error_code, lease_epoch, task_epoch, parent_task_epoch,
       external_worker_id, external_lease_expires_at, external_claim_epoch, objects,
       next_replayable, error_data, superseded_at
FROM process_instances
WHERE process_instances.id IN (SELECT subtree.id FROM subtree)
  AND (process_instances.id = ?1
       OR status NOT IN ('completed', 'failed', 'raised'))
ORDER BY created_at ASC, id ASC
`

// The instance and every DESCENDANT that is still live, oldest first. Terminal descendants
// are excluded on purpose: their outputs are frozen and nothing re-runs them, so they are
// not part of the unit that moves. specs/version-compatibility.md s3c.
//
// The root is returned whatever its status, because `failed` is a state an upgrade is FOR
// (move it, then retry it on the new version) and a root filtered out of its own subtree
// reads as "no tree to move". A failed root has no live descendants anyway: a parent
// poisoned by a child goes to `failing`, and the claim predicate refuses a waiting row, so
// it cannot settle to `failed` until its children are terminal.
func (q *Queries) NonTerminalSubtree(ctx context.Context, root string) ([]ProcessInstance, error) {
	rows, err := q.db.QueryContext(ctx, nonTerminalSubtree, root)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ProcessInstance
	for rows.Next() {
		var i ProcessInstance
		if err := rows.Scan(
			&i.ID,
			&i.ProcessName,
			&i.ProcessVersion,
			&i.ParentID,
			&i.CallStack,
			&i.RetryCount,
			&i.WakeAt,
			&i.Status,
			&i.ErrorMessage,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.WorkerID,
			&i.LeaseExpiresAt,
			&i.WaitState,
			&i.SpawnTaskID,
			&i.InputData,
			&i.OutputsData,
			&i.OutputData,
			&i.ErrorInternal,
			&i.ExternalData,
			&i.EngineState,
			&i.Task,
			&i.ErrorCode,
			&i.LeaseEpoch,
			&i.TaskEpoch,
			&i.ParentTaskEpoch,
			&i.ExternalWorkerID,
			&i.ExternalLeaseExpiresAt,
			&i.ExternalClaimEpoch,
			&i.Objects,
			&i.NextReplayable,
			&i.ErrorData,
			&i.SupersededAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

