// Conditional on everything that would make the migration stale. process_version and task
// pin what the state was conformed against. status keeps it to the settled states -- a
// running instance can be claimed and advanced between the read and this write, and the
// task predicate is what turns that into a lost race a re-run picks up rather than a
// clobber.
//
// worker_id IS NULL is defence, not a live case: a claim only takes running/failing/pausing
// rows, so a paused or failed one is never leased. It is here because the status filter and
// the claim predicate are separate statements that could drift apart, and this write must
// not be the place that discovers it.
func (q *Queries) UpgradeInstanceVersion(ctx context.Context, arg UpgradeInstanceVersionParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, upgradeInstanceVersion,
		arg.ToVersion,
		arg.InputData,
		arg.OutputsData,
		arg.OutputData,
		arg.ErrorInternal,
		arg.ErrorData,
		arg.ExternalData,
		arg.EngineState,
		arg.Objects,
		arg.UpdatedAt,
		arg.ID,
		arg.FromVersion,
		arg.Task,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

const upsertChannel = `-- name: UpsertChannel :exec
INSERT INTO process_channels (name, channel, version, updated_at)
VALUES (?1, ?2, ?3, ?4)
ON CONFLICT (name, channel) DO UPDATE SET version = EXCLUDED.version, updated_at = EXCLUDED.updated_at
`

type UpsertChannelParams struct {
	Name      string
	Channel   string
	Version   int64
	UpdatedAt int64
}

func (q *Queries) UpsertChannel(ctx context.Context, arg UpsertChannelParams) error {
	_, err := q.db.ExecContext(ctx, upsertChannel,
		arg.Name,
		arg.Channel,
		arg.Version,
		arg.UpdatedAt,
	)
	return err
}

const wakeParent = `-- name: WakeParent :exec
UPDATE process_instances
SET wait_state = CASE WHEN status IN ('running', 'pausing', 'paused')
                      THEN 'collecting' ELSE '' END,
    updated_at = ?1
WHERE id = ?2
`

type WakeParentParams struct {
	UpdatedAt int64
	ID        string
}

// A healthy parent moves to 'collecting' to merge its children's outputs; a doomed
// one ('failing') clears the wait state and just settles. A paused parent is healthy
// (it is suspended, not doomed) so it is armed for the collect it will run when
// resumed. Its status keeps it unclaimable in the meantime.
func (q *Queries) WakeParent(ctx context.Context, arg WakeParentParams) error {
	_, err := q.db.ExecContext(ctx, wakeParent, arg.UpdatedAt, arg.ID)
	return err
}
